use Inertia\Inertia;
class QuoteTemplateController extends Controller { public function index(){return Inertia::render('QuoteTemplates/Index',['templates'=>QuoteTemplate::with('license')->latest()->get()]);} public function store(Request $request){$data=$request->validate(['name'=>['required','string','max:120'],'type'=>['nullable','in:oferta,deviz'],'license_id'=>['nullable','exists:licenses,id'],'title'=>['nullable','string','max:255'],'discount'=>['nullable','numeric','min:0','max:100'],'vat_rate'=>['nullable','numeric','min:0','max:100'],'notes'=>['nullable','string'],'items'=>['required','array','min:1'],'items.*.product_id'=>['nullable','exists:products,id'],'items.*.type'=>['nullable','string','max:30'],'items.*.name'=>['required','string','max:255'],'items.*.unit'=>['nullable','string','max:30'],'items.*.quantity'=>['required','numeric','min:0.001'],'items.*.unit_price'=>['required','numeric','min:0'],'items.*.discount'=>['nullable','numeric','min:0','max:100']]);QuoteTemplate::create(['name'=>$data['name'],'type'=>$data['type']??'oferta','license_id'=>$data['license_id']??null,'title'=>$data['title']??null,'discount'=>$data['discount']??0,'vat_rate'=>$data['vat_rate']??21,'notes'=>$data['notes']??null,'items'=>collect($data['items'])->map(fn($item)=>collect($item)->only(['product_id','type','name','unit','quantity','unit_price','discount'])->all())->all(),'created_by'=>$request->user()->id]);return redirect()->route('quote-templates.index')->with('success','Șablonul a fost salvat și poate fi reutilizat.');} public function storeFromQuote(Request $request,Quote $quote){$data=$request->validate(['name'=>['required','string','max:120']]);$quote->load('items');QuoteTemplate::create(['name'=>$data['name'],'type'=>$quote->type,'license_id'=>$quote->license_id,'title'=>$quote->title,'discount'=>$quote->discount,'vat_rate'=>$quote->vat_rate,'notes'=>$quote->notes,'items'=>$quote->items->map(fn($item)=>$item->only(['product_id','type','name','unit','quantity','unit_price','discount']))->values()->all(),'created_by'=>$request->user()->id]);return back()->with('success','Șablonul de ofertă a fost salvat.');} public function destroy(QuoteTemplate $quoteTemplate){$quoteTemplate->delete();return back()->with('success','Șablonul a fost șters.');} }
